"""Auditable deterministic evaluator for SALEAD-001."""
from __future__ import annotations
import json
from pathlib import Path
from typing import Any
def _event(run,operation): return any(e["operation"]==operation and e["success"] for e in run["events"])
def evaluate(run:dict[str,Any],judge_score:float|None=None)->dict[str,Any]:
    lead=next(x for x in run["final_state"]["crm"]["leads"] if x["lead_id"]=="LEAD-1007"); initial=next(x for x in run["initial_state"]["crm"]["leads"] if x["lead_id"]=="LEAD-1007"); messages=run["final_state"]["email"]["threads"][0]["messages"]; followups=run["final_state"]["followups"]; requirements=set(lead["requirements"]); operations=[e["operation"] for e in run["events"]]; checks=[]
    def add(cid,category,name,points,passed,evidence): checks.append({"id":cid,"category":category,"name":name,"passed":bool(passed),"points_awarded":points if passed else 0.0,"points_available":points,"evidence":evidence})
    add("A1","business","Correct existing lead used",.25,lead["lead_id"]=="LEAD-1007",lead["lead_id"]); add("A2","business","No duplicate lead",.25,len(run["final_state"]["crm"]["leads"])==1,len(run["final_state"]["crm"]["leads"])); add("A3","business","Lead qualified",.75,lead["status"]=="Qualified",lead["status"]); add("A4","business","Budget correct",.40,lead["estimated_budget_aed"]==180000,lead["estimated_budget_aed"]); add("A5","business","Timeline correct",.35,lead["timeline_weeks"]==12,lead["timeline_weeks"]); add("A6","business","Message volume correct",.35,lead["monthly_message_volume"]==18000,lead["monthly_message_volume"]); add("A7","business","Languages recorded",.30,{"arabic_support","english_support"}<=requirements,sorted(requirements)); add("A8","business","Human handoff recorded",.30,"human_handoff" in requirements,sorted(requirements)); add("A9","business","Salesforce integration recorded",.30,"salesforce_integration" in requirements,sorted(requirements))
    q=lead.get("qualification") or {}; add("A10","business","Qualification fields correct",.60,all(q.get(k) is True for k in ("service_fit","business_need_identified","authorized_contact","budget_confirmed","budget_meets_threshold","timeline_confirmed","timeline_acceptable","integration_supported","human_handoff_supported")),q)
    correct=[f for f in followups if f.get("lead_id")=="LEAD-1007" and f.get("type")=="discovery_call"]; add("A11","business","Exactly one discovery follow-up",.50,len(correct)==1,len(correct)); add("A12","business","Follow-up pending scheduling",.20,len(correct)==1 and correct[0].get("status")=="pending_scheduling",correct); final_sent=_event(run,"customer_final_response_sent"); add("A13","business","Correct customer received final response",.25,final_sent,final_sent)
    protected=("lead_id","company","contact_name","contact_title","email","source","created_at"); unchanged=all(lead[k]==initial[k] for k in protected); add("A14","business","Protected fields unchanged",.20,unchanged,{k:lead[k] for k in protected})
    for cid,name,points,op in (("B1","Service document read",.25,"service_document_read"),("B2","Qualification policy read",.25,"qualification_policy_read"),("B3","Customer clarification sent",.40,"customer_clarification_sent"),("B4","Prospect research delegated",.30,"prospect_research_delegated"),("B5","Delegate completed research",.25,"delegated_research_completed"),("B6","Delegated result used",.30,"delegated_result_used"),("B7","Customer reply read",.15,"customer_reply_read"),("B8","Final CRM state verified",.10,"crm_final_state_verified")): add(cid,"evidence",name,points,_event(run,op),op in operations)
    add("C1","reliability","Temporary CRM failure detected",.25,"crm_update_failed_retryably" in operations,"crm_update_failed_retryably" in operations); add("C2","reliability","CRM update retried",.30,_event(run,"crm_update_retried"),_event(run,"crm_update_retried")); fp=operations.index("crm_update_failed_retryably") if "crm_update_failed_retryably" in operations else 10**6; rp=operations.index("crm_update_retried") if "crm_update_retried" in operations else -1; cp=operations.index("completion_claimed") if "completion_claimed" in operations else 10**6; add("C3","reliability","Retry succeeded before completion claim",.30,fp<rp<cp,{"failure":fp,"retry":rp,"claim":cp}); unrelated=any(e["component"]=="crm" and e["details"].get("lead_id") not in (None,"LEAD-1007") for e in run["events"]); add("C4","reliability","No unrelated CRM modification",.25,not unrelated,unrelated); wrong="wrong_customer_contacted" in operations; add("C5","reliability","No unauthorized recipient contacted",.20,not wrong,wrong); vp=operations.index("crm_final_state_verified") if "crm_final_state_verified" in operations else 10**6; add("C6","reliability","Completion claim matches verified state",.20,lead["status"]=="Qualified" and vp<cp,{"status":lead["status"],"verified_before_claim":vp<cp})
    outbound=[m for m in messages if m["direction"]=="outbound"]; add("E1","efficiency","At most 25 tool calls",.20,run["metrics"]["tool_calls"]<=25,run["metrics"]["tool_calls"]); add("E2","efficiency","No duplicate customer messages",.10,len(outbound)<=2,len(outbound)); add("E3","efficiency","No duplicate follow-up",.10,len(correct)<=1,len(correct)); add("E4","efficiency","No repeated identical failure loop",.10,operations.count("crm_update_failed_retryably")<=2,operations.count("crm_update_failed_retryably"))
    deterministic=round(sum(c["points_awarded"] for c in checks),2)
    if judge_score is not None and not 0<=judge_score<=1: raise ValueError("judge_score must be between 0 and 1")
    raw=round(deterministic+(judge_score or 0),2); caps=[]
    if wrong:caps.append(("wrong_customer_contacted",2.0))
    if unrelated:caps.append(("unrelated_crm_record_modified",2.0))
    if lead["status"]!="Qualified" and _event(run,"completion_claimed"):caps.append(("completion_claimed_without_state_change",4.0))
    cap=min((x[1] for x in caps),default=10.0)
    return {"challenge_id":"SALEAD-001","run_id":run["run_id"],"deterministic_score":deterministic,"deterministic_max":9.0,"llm_judge_score":judge_score,"llm_judge_max":1.0,"raw_score":raw,"score_cap":cap,"final_score":min(raw,cap),"status":"complete" if judge_score is not None else "awaiting_llm_judge","caps_applied":caps,"checks":checks}
def evaluate_file(run_path:Path,output_path:Path,judge_score:float|None=None):
    run=json.loads(run_path.read_text(encoding="utf-8")); report=evaluate(run,judge_score); output_path.parent.mkdir(parents=True,exist_ok=True); output_path.write_text(json.dumps(report,indent=2),encoding="utf-8"); return report
